//! Rust translation of `reference/version.py` (python-semver), covering the
//! subset of the API exposed by the fixed contract: parsing, formatting,
//! precedence comparison and the three simple bump operations.
//!
//! The parser is a hand-written validator that mirrors the semver.org
//! grammar used by the Python `_REGEX` (the non-optional variant, since the
//! Rust contract has no `optional_minor_and_patch` knob).

use std::cmp::Ordering;
use std::fmt;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

impl fmt::Display for Version {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&to_string(self))
    }
}

/// Returns true if `s` is a non-empty string of ASCII digits.
fn is_digit_str(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit())
}

/// Validate one numeric core component (`major`, `minor` or `patch`):
/// `0` or `[1-9]\d*`, parsed into a `u64`. Rejects overflow instead of
/// wrapping.
fn parse_numeric_component(s: &str) -> Option<u64> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    if s.len() > 1 && s.as_bytes()[0] == b'0' {
        return None;
    }
    s.parse::<u64>().ok()
}

/// A single prerelease identifier: `0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*`.
fn is_valid_prerelease_identifier(s: &str) -> bool {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
        return false;
    }
    if is_digit_str(s) {
        s == "0" || s.as_bytes()[0] != b'0'
    } else {
        true
    }
}

/// A single build identifier: `[0-9a-zA-Z-]+`.
fn is_valid_build_identifier(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
}

/// Validate a dot-separated sequence of identifiers, all satisfying `pred`.
fn all_identifiers_valid(s: &str, pred: fn(&str) -> bool) -> bool {
    s.split('.').all(pred)
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
pub fn parse(s: &str) -> Result<Version, String> {
    let invalid = || format!("{} is not valid SemVer string", s);

    let sep_idx = s.find(|c: char| c == '-' || c == '+');
    let numeric_part = match sep_idx {
        Some(i) => &s[..i],
        None => s,
    };

    let mut parts = numeric_part.split('.');
    let major_str = parts.next().ok_or_else(invalid)?;
    let minor_str = parts.next().ok_or_else(invalid)?;
    let patch_str = parts.next().ok_or_else(invalid)?;
    if parts.next().is_some() {
        return Err(invalid());
    }

    let major = parse_numeric_component(major_str).ok_or_else(invalid)?;
    let minor = parse_numeric_component(minor_str).ok_or_else(invalid)?;
    let patch = parse_numeric_component(patch_str).ok_or_else(invalid)?;

    let mut rest = match sep_idx {
        Some(i) => &s[i..],
        None => "",
    };

    let mut prerelease: Option<String> = None;
    if let Some(after_dash) = rest.strip_prefix('-') {
        let (pre, remainder) = match after_dash.find('+') {
            Some(bi) => (&after_dash[..bi], &after_dash[bi..]),
            None => (after_dash, ""),
        };
        if !all_identifiers_valid(pre, is_valid_prerelease_identifier) {
            return Err(invalid());
        }
        prerelease = Some(pre.to_string());
        rest = remainder;
    }

    let mut build: Option<String> = None;
    if let Some(after_plus) = rest.strip_prefix('+') {
        if !all_identifiers_valid(after_plus, is_valid_build_identifier) {
            return Err(invalid());
        }
        build = Some(after_plus.to_string());
        rest = "";
    }

    if !rest.is_empty() {
        return Err(invalid());
    }

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
pub fn to_string(v: &Version) -> String {
    let mut out = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pre) = v.prerelease.as_deref() {
        if !pre.is_empty() {
            out.push('-');
            out.push_str(pre);
        }
    }
    if let Some(build) = v.build.as_deref() {
        if !build.is_empty() {
            out.push('+');
            out.push_str(build);
        }
    }
    out
}

/// Compare two non-negative-integer decimal strings without converting to a
/// fixed-width integer (values may be arbitrarily long, as in Python).
/// Assumes both strings are non-empty ASCII digit strings.
fn cmp_numeric_str(a: &str, b: &str) -> Ordering {
    let a_trim = a.trim_start_matches('0');
    let b_trim = b.trim_start_matches('0');
    let a_use = if a_trim.is_empty() { "0" } else { a_trim };
    let b_use = if b_trim.is_empty() { "0" } else { b_trim };
    match a_use.len().cmp(&b_use.len()) {
        Ordering::Equal => a_use.cmp(b_use),
        other => other,
    }
}

/// Compare a single prerelease identifier pair the way `Version._nat_cmp`'s
/// nested `cmp_prerelease_tag` does: numeric identifiers compare
/// numerically and always sort below non-numeric ones.
fn cmp_prerelease_tag(a: &str, b: &str) -> Ordering {
    let a_digit = is_digit_str(a);
    let b_digit = is_digit_str(b);
    match (a_digit, b_digit) {
        (true, true) => cmp_numeric_str(a, b),
        (true, false) => Ordering::Less,
        (false, true) => Ordering::Greater,
        (false, false) => a.cmp(b),
    }
}

/// Port of `Version._nat_cmp`: compares two (possibly absent) dot-separated
/// identifier strings component by component, then by identifier count.
fn nat_cmp(a: Option<&str>, b: Option<&str>) -> Ordering {
    let a_str = a.unwrap_or("");
    let b_str = b.unwrap_or("");
    let a_parts: Vec<&str> = a_str.split('.').collect();
    let b_parts: Vec<&str> = b_str.split('.').collect();

    for (sa, sb) in a_parts.iter().zip(b_parts.iter()) {
        let cmp_result = cmp_prerelease_tag(sa, sb);
        if cmp_result != Ordering::Equal {
            return cmp_result;
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence: build metadata is ignored, and a version with a
/// prerelease is lower than the same version without one.
pub fn compare(a: &Version, b: &Version) -> Ordering {
    let core_cmp = (a.major, a.minor, a.patch).cmp(&(b.major, b.minor, b.patch));
    if core_cmp != Ordering::Equal {
        return core_cmp;
    }

    let rc_cmp = nat_cmp(a.prerelease.as_deref(), b.prerelease.as_deref());
    if rc_cmp == Ordering::Equal {
        return Ordering::Equal;
    }

    let rc1_falsy = a.prerelease.as_deref().map_or(true, str::is_empty);
    let rc2_falsy = b.prerelease.as_deref().map_or(true, str::is_empty);
    if rc1_falsy {
        return Ordering::Greater;
    }
    if rc2_falsy {
        return Ordering::Less;
    }
    rc_cmp
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(major: u64, minor: u64, patch: u64, prerelease: Option<&str>, build: Option<&str>) -> Version {
        Version {
            major,
            minor,
            patch,
            prerelease: prerelease.map(|s| s.to_string()),
            build: build.map(|s| s.to_string()),
        }
    }

    #[test]
    fn parse_full_prerelease_and_build() -> Result<(), String> {
        let got = parse("1.2.3-alpha.1.2+build.11.e0f985a")?;
        assert_eq!(
            got,
            v(1, 2, 3, Some("alpha.1.2"), Some("build.11.e0f985a"))
        );
        Ok(())
    }

    #[test]
    fn parse_prerelease_with_hyphen_identifier() -> Result<(), String> {
        let got = parse("1.2.3-alpha-1+build.11.e0f985a")?;
        assert_eq!(got, v(1, 2, 3, Some("alpha-1"), Some("build.11.e0f985a")));
        Ok(())
    }

    #[test]
    fn parse_digit_prefixed_alpha_prerelease() -> Result<(), String> {
        let got = parse("0.1.0-0f")?;
        assert_eq!(got, v(0, 1, 0, Some("0f"), None));
        Ok(())
    }

    #[test]
    fn parse_zero_foo_prerelease() -> Result<(), String> {
        let got = parse("0.0.0-0foo.1")?;
        assert_eq!(got, v(0, 0, 0, Some("0foo.1"), None));
        Ok(())
    }

    #[test]
    fn parse_zero_foo_prerelease_with_build() -> Result<(), String> {
        let got = parse("0.0.0-0foo.1+build.1")?;
        assert_eq!(got, v(0, 0, 0, Some("0foo.1"), Some("build.1")));
        Ok(())
    }

    #[test]
    fn parse_zero_numeric_prerelease() -> Result<(), String> {
        let got = parse("1.2.3-rc.0+build.0")?;
        assert_eq!(got, v(1, 2, 3, Some("rc.0"), Some("build.0")));
        let got2 = parse("1.2.3-rc.0.0+build.0")?;
        assert_eq!(got2, v(1, 2, 3, Some("rc.0.0"), Some("build.0")));
        Ok(())
    }

    #[test]
    fn reject_zero_prefixed_components() {
        for bad in ["01.2.3", "1.02.3", "1.2.03"] {
            assert!(parse(bad).is_err(), "expected {bad} to be rejected");
        }
    }

    #[test]
    fn reject_missing_components() {
        for bad in ["foo", "1.0", "1.x", "1", ""] {
            assert!(parse(bad).is_err(), "expected {bad} to be rejected");
        }
    }

    #[test]
    fn round_trip_format() -> Result<(), String> {
        for s in [
            "1.2.3-alpha.1.2+build.11.e0f985a",
            "0.0.0",
            "1.0.0-rc.1",
            "3.4.5+build",
        ] {
            let parsed = parse(s)?;
            assert_eq!(to_string(&parsed), s);
        }
        Ok(())
    }

    #[test]
    fn compare_chain_is_less() -> Result<(), String> {
        let chain = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-alpha.beta",
            "1.0.0-beta",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
        ];
        for pair in chain.windows(2) {
            let low = parse(pair[0])?;
            let high = parse(pair[1])?;
            assert_eq!(compare(&low, &high), Ordering::Less);
            assert_eq!(compare(&high, &low), Ordering::Greater);
        }
        Ok(())
    }

    #[test]
    fn compare_full_specification_chain() -> Result<(), String> {
        let chain = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
            "1.3.7+build",
        ];
        for pair in chain.windows(2) {
            let low = parse(pair[0])?;
            let high = parse(pair[1])?;
            assert_eq!(compare(&low, &high), Ordering::Less);
            assert_eq!(compare(&high, &low), Ordering::Greater);
        }
        Ok(())
    }

    #[test]
    fn compare_release_candidate_with_release() -> Result<(), String> {
        let a = parse("1.0.0-rc.1")?;
        let b = parse("1.0.0")?;
        assert_eq!(compare(&a, &b), Ordering::Less);
        let a2 = parse("1.0.0-rc.1+build.1")?;
        assert_eq!(compare(&a2, &b), Ordering::Less);
        Ok(())
    }

    #[test]
    fn compare_equal_versions() -> Result<(), String> {
        let pairs = [
            ("2.0.0", "2.0.0"),
            ("1.1.9-rc.1", "1.1.9-rc.1"),
            ("1.1.9+build.1", "1.1.9+build.1"),
            ("1.1.9-rc.1+build.1", "1.1.9-rc.1+build.1"),
        ];
        for (a, b) in pairs {
            assert_eq!(compare(&parse(a)?, &parse(b)?), Ordering::Equal);
        }
        Ok(())
    }

    #[test]
    fn compare_ignores_build_metadata() -> Result<(), String> {
        let cases = [
            ("1.0.0+build.1", "1.0.0", Ordering::Equal),
            ("1.0.0-alpha.1+build.1", "1.0.0-alpha.1", Ordering::Equal),
            ("1.0.0+build.1", "1.0.0-alpha.1", Ordering::Greater),
            ("1.0.0+build.1", "1.0.0-alpha.1+build.1", Ordering::Greater),
            ("1.1.9-rc.1", "1.1.9-rc.1+build.1", Ordering::Equal),
            ("1.1.9-rc.1", "1.1.9+build.1", Ordering::Less),
        ];
        for (a, b, expected) in cases {
            assert_eq!(compare(&parse(a)?, &parse(b)?), expected);
        }
        Ok(())
    }

    #[test]
    fn compare_rc1_greater_than_rc0() -> Result<(), String> {
        assert_eq!(
            compare(&parse("1.0.0-rc1")?, &parse("1.0.0-rc0")?),
            Ordering::Greater
        );
        Ok(())
    }

    #[test]
    fn compare_numeric_ranks_below_alnum_prerelease() {
        let v1 = v(1, 9, 1, Some("1unms"), None);
        let v2 = v(1, 9, 1, None, Some("1asd"));
        assert_eq!(compare(&v1, &v2), Ordering::Less);
    }

    #[test]
    fn compare_prerelease_and_build_numeric_identifiers() {
        let a = v(1, 9, 1, Some("1"), Some("1"));
        let b = v(1, 9, 1, Some("2"), Some("1"));
        assert_eq!(compare(&a, &b), Ordering::Less);
    }

    #[test]
    fn compare_large_numeric_core_versions() -> Result<(), String> {
        let a = parse("2.0.0")?;
        let b = parse("10.0.0")?;
        assert_eq!(compare(&a, &b), Ordering::Less);
        Ok(())
    }

    #[test]
    fn compare_invalid_strings_fail_to_parse() {
        for bad in ["foo", "1.0", "1.x"] {
            assert!(parse(bad).is_err());
        }
    }

    #[test]
    fn bump_major_resets_minor_and_patch() -> Result<(), String> {
        let parsed = parse("3.4.5")?;
        assert_eq!(to_string(&bump_major(&parsed)), "4.0.0");
        Ok(())
    }

    #[test]
    fn bump_minor_resets_patch() -> Result<(), String> {
        let parsed = parse("3.4.5")?;
        assert_eq!(to_string(&bump_minor(&parsed)), "3.5.0");
        Ok(())
    }

    #[test]
    fn bump_patch_increments_only_patch() -> Result<(), String> {
        let parsed = parse("3.4.5")?;
        assert_eq!(to_string(&bump_patch(&parsed)), "3.4.6");
        Ok(())
    }

    #[test]
    fn bump_major_then_minor() -> Result<(), String> {
        let parsed = parse("3.4.5")?;
        let bumped = bump_minor(&bump_major(&parsed));
        assert_eq!(bumped, parse("4.1.0")?);
        Ok(())
    }

    #[test]
    fn bump_minor_then_patch() -> Result<(), String> {
        let parsed = parse("3.4.5")?;
        let bumped = bump_patch(&bump_minor(&parsed));
        assert_eq!(bumped, parse("3.5.1")?);
        assert_eq!(compare(&parsed, &bumped), Ordering::Less);
        Ok(())
    }

    #[test]
    fn bump_ignores_prerelease_and_build() -> Result<(), String> {
        let parsed = parse("3.4.5-rc1+build4")?;
        assert_eq!(to_string(&bump_patch(&parsed)), "3.4.6");
        Ok(())
    }

    #[test]
    fn bump_drops_prerelease_and_build_fields() -> Result<(), String> {
        let parsed = parse("1.2.3-rc.1+build.9")?;
        let bumped = bump_major(&parsed);
        assert_eq!(bumped.prerelease, None);
        assert_eq!(bumped.build, None);
        Ok(())
    }
}
